def S(n):
    # n is a positive integer, 1 <= n <= 12
    # p = 13 + n
    # q = 170 - n**2
    return (12 + n) / (13 + n) + (13 - n) / (170 - n**2)

# Check integer values around the suspected maximum n* ~ 4.352
n_values = [1, 2, 3, 4, 5, 6, 11, 12]
results = {}
for n in n_values:
    results[n] = S(n)

print("S(n) values for integer n:")
for n, s_val in results.items():
    print(f"n={n}: S = {s_val}")
